package main

import "strings"

func magenta(s string) string { return "\x1b[95m" + s + "\x1b[0m" }
func cyan(s string) string    { return "\x1b[96m" + s + "\x1b[0m" }
func green(s string) string   { return "\x1b[92m" + s + "\x1b[0m" }
func grey(s string) string    { return "\x1b[90m" + s + "\x1b[0m" }

type jsonColor int

const (
	colNone jsonColor = iota
	colMagenta
	colCyan
)

func (c jsonColor) code() string {
	switch c {
	case colMagenta:
		return "\x1b[95m"
	case colCyan:
		return "\x1b[96m"
	}
	return ""
}

// colorizeJSON reproduces the stateful colouring applied to JSON bodies
// when output is a terminal.
func colorizeJSON(s string) string {
	var out strings.Builder
	pending := colNone
	tokenActive := false
	inString := false
	inBareString := false

	for i := 0; i < len(s); i++ {
		c := s[i]

		if inString {
			if c == '\\' && i+1 < len(s) {
				out.WriteByte(c)
				i++
				out.WriteByte(s[i])
				continue
			}
			if c == '"' {
				out.WriteString("\x1b[0m\"")
				inString = false
				tokenActive = false
				pending = colNone
				continue
			}
			out.WriteByte(c)
			continue
		}

		switch c {
		case '"':
			if inBareString {
				out.WriteString("\x1b[0m\"")
				inBareString = false
				tokenActive = false
				pending = colNone
			} else if pending != colNone {
				out.WriteByte('"')
				out.WriteString(pending.code())
				inString = true
				tokenActive = true
			} else {
				out.WriteString("\x1b[0m\"")
				inBareString = true
				tokenActive = false
			}
		case '{':
			out.WriteByte(c)
			pending = colMagenta
			tokenActive = false
		case '[':
			out.WriteByte(c)
			tokenActive = false
		case '}':
			out.WriteByte(c)
			tokenActive = true
		case ']':
			out.WriteByte(c)
		case ':', ',':
			if !inBareString && tokenActive {
				out.WriteString("\x1b[0m")
			}
			out.WriteByte(c)
			tokenActive = false
			if c == ':' {
				pending = colCyan
			} else {
				pending = colMagenta
			}
		case ' ', '\t', '\n', '\r':
			out.WriteByte(c)
		default:
			if !tokenActive {
				if pending != colNone {
					out.WriteString(pending.code())
				}
				tokenActive = true
			}
			out.WriteByte(c)
		}
	}
	return out.String()
}
