{"command":"cat > http.go << 'EOF'
package main

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"net/url"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

var headersMap = map[string]string{}
var paramsMap = map[string]string{}
var filesMap = map[string]string{}

// checkFiles validates the file-upload style combination.
func checkFiles() {
	if len(filesMap) > 0 && !jsonValue && !formValue {
		log.Fatal("file upload only support in forms style: -f=true")
	}
}

func acceptValue() string {
	if jsonValue || (!formValue && methodValue != "GET") {
		return "application/json"
	}
	return "*/*"
}

func encodeParams(values map[string]string) string {
	parts := make([]string, 0, len(values))
	for k, v := range values {
		parts = append(parts, url.QueryEscape(k)+"="+url.QueryEscape(v))
	}
	return strings.Join(parts, "&")
}

func authHeaderValue(auth string) string {
	transformed := auth
	if strings.Count(auth, ":") != 1 {
		transformed = auth + ":"
	}
	return "Basic " + base64.StdEncoding.EncodeToString([]byte(transformed))
}

type requestInfo struct {
	req       *http.Request
	client    *http.Client
	bodyBytes []byte
}

func buildRequest(finalURL string, parsed *url.URL, client *http.Client, isMultipart *bool) *requestInfo {
	u, err := url.Parse(finalURL)
	if err != nil {
		u = parsed
	}
	_ = u
	isGET := methodValue == "GET"
	inBodyMethods := methodValue == "POST" || methodValue == "PUT" || methodValue == "PATCH"

	var bodyBytes []byte
	var generatedCT string
	multipartRequest := false

	if rawBodyValue != "" {
		bodyBytes = []byte(rawBodyValue)
		if !isGET && !formValue && len(paramsMap) > 0 {
			generatedCT = "application/json"
		}
	} else if isGET {
		bodyBytes = nil
	} else if formValue {
		if inBodyMethods {
			if !jsonValue && len(filesMap) > 0 {
				var boundary string
				bodyBytes, boundary = buildMultipartBody(filesMap, paramsMap)
				generatedCT = "multipart/form-data; boundary=" + boundary
				multipartRequest = true
			} else if len(paramsMap) > 0 {
				bodyBytes = []byte(encodeParams(paramsMap))
				generatedCT = "application/x-www-form-urlencoded"
			}
		}
	} else {
		if len(paramsMap) > 0 {
			var buf bytes.Buffer
			enc := json.NewEncoder(&buf)
			_ = enc.Encode(paramsMap)
			bodyBytes = buf.Bytes()
			generatedCT = "application/json"
		}
	}
	if isMultipart != nil {
		*isMultipart = multipartRequest
	}

	req := &http.Request{
		Method:        methodValue,
		URL:           parsed,
		Proto:         "HTTP/1.1",
		ProtoMajor:    1,
		ProtoMinor:    1,
		Header:        make(http.Header),
		Host:          "",
		ContentLength: 0,
	}
	// Use the freshly parsed final URL if available.
	if u != nil {
		req.URL = u
	}

	req.Header.Set("Accept", acceptValue())
	req.Header.Set("Accept-Encoding", "gzip, deflate")

	for k, v := range headersMap {
		if k == "Host" {
			req.Host = v
		} else {
			req.Header.Set(k, v)
		}
	}

	if parsed != nil && parsed.User != nil {
		user := parsed.User.Username()
		pass, _ := parsed.User.Password()
		req.Header.Set("Authorization", "Basic "+base64.StdEncoding.EncodeToString([]byte(user+":"+pass)))
	}
	if authValue != "" {
		req.Header.Set("Authorization", authHeaderValue(authValue))
	}
	if req.Header.Get("User-Agent") == "" {
		req.Header.Set("User-Agent", "bat/0.1.0")
	}
	if generatedCT != "" {
		req.Header.Set("Content-Type", generatedCT)
	}

	if bodyBytes != nil {
		req.Body = &readCloserFromBytes{Reader: bytes.NewReader(bodyBytes)}
		if multipartRequest {
			req.ContentLength = 0
		} else {
			req.ContentLength = int64(len(bodyBytes))
		}
	}

	if parsed != nil && parsed.User != nil && req.URL != nil {
		// Authorization has been copied into the header, matching
		// the behaviour observed on the wire.
	}

	return &requestInfo{req: req, client: client, bodyBytes: bodyBytes}
}

type readCloserFromBytes struct {
	*bytes.Reader
}

func (r *readCloserFromBytes) Close() error { return nil }

var jsonContentTypeRe = regexp.MustCompile(`application/.*json`)

func isJSONContentType(ct string) bool {
	return jsonContentTypeRe.MatchString(ct)
}

func responseHeaderMap(resp *http.Response) map[string][]string {
	out := make(map[string][]string, len(resp.Header))
	for k, vals := range resp.Header {
		cp := make([]string, len(vals))
		copy(cp, vals)
		out[k] = cp
	}
	if resp.ContentLength >= 0 {
		out["Content-Length"] = []string{strconv.FormatInt(resp.ContentLength, 10)}
	}
	return out
}

func printResponseHeaders(resp *http.Response, downloadStyle bool) {
	fmt.Println(magenta(resp.Proto) + " " + green(resp.Status))
	headers := responseHeaderMap(resp)
	for k, vals := range headers {
		v := strings.Join(vals, " ")
		if downloadStyle {
			fmt.Printf("%s : %s\n", grey(k), cyan(v))
		} else {
			fmt.Printf("%s: %s\n", grey(k), cyan(v))
		}
	}
	fmt.Println()
}

func requestDump(info *requestInfo) (string, string) {
	req := info.req
	method := req.Method
	if method == "" {
		method = "GET"
	}
	uri := req.URL.RequestURI()
	proto := req.Proto
	if proto == "" {
		proto = "HTTP/1.1"
	}
	var b strings.Builder
	b.WriteString(method + " " + uri + " " + proto + "\r\n")
	host := req.Host
	if host == "" {
		host = req.URL.Host
	}
	if host != "" {
		b.WriteString("Host: " + host + "\r\n")
	}
	keys := make([]string, 0, len(req.Header))
	for k := range req.Header {
		canonical := http.CanonicalHeaderKey(k)
		if canonical == "Host" || canonical == "Transfer-Encoding" || canonical == "Trailer" {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		for _, v := range req.Header[k] {
			b.WriteString(k + ": " + v + "\r\n")
		}
	}
	return b.String(), string(info.bodyBytes)
}

func printRequestHeaders(info *requestInfo) {
	headerText, _ := requestDump(info)
