	"net/http"
	"sort"
	"strings"
	"time"
)

type benchRequest struct {
	req    *http.Request
	client *http.Client
}

type benchResult struct {
	duration      float64
	statusCode    int
	contentLength int64
	err           error
}

func RunBench(br *benchRequest) {
	num := benchNumValue
	conc := benchConcValue
	results := make(chan benchResult, num)
	jobs := make(chan struct{})

	for i := 0; i < conc; i++ {
		go func() {
			for range jobs {
				start := time.Now()
				resp, err := br.client.Do(br.req)
				if err != nil {
					results <- benchResult{err: err}
					continue
				}
				elapsed := time.Since(start).Seconds()
				cl := resp.ContentLength
				code := resp.StatusCode
				resp.Body.Close()
				results <- benchResult{duration: elapsed, statusCode: code, contentLength: cl}
			}
		}()
	}

	startBench := time.Now()
	for i := 0; i < num; i++ {
		jobs <- struct{}{}
	}
	close(jobs)

	var latencies []float64
	statusCodes := map[int]int{}
	errorDist := map[string]int{}
	var totalData int64
	for i := 0; i < num; i++ {
		r := <-results
		if r.err != nil {
			errorDist[r.err.Error()]++
			continue
		}
