{"command":"cat > progress.go << 'EOF'
package main

import (
	"fmt"
	"io"
	"strings"
	"time"
)

func formatBytesInt(n int64) string {
	if n < 1024 {
		return fmt.Sprintf("%d B", n)
	} else if n < 1024*1024 {
		return fmt.Sprintf("%.2f KB", float64(n)/1024)
	} else if n < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MB", float64(n)/(1024*1024))
	} else if n < 1024*1024*1024*1024 {
		return fmt.Sprintf("%.2f GB", float64(n)/(1024*1024*1024))
	}
	return fmt.Sprintf("%.2f TB", float64(n)/(1024*1024*1024*1024))
}

func formatSpeed(speed float64) string {
	if speed < 1024 {
		return fmt.Sprintf("%d B", int(speed))
	} else if speed < 1024*1024 {
		return fmt.Sprintf("%.2f KB", speed/1024)
	} else if speed < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MB", speed/(1024*1024))
	} else if speed < 1024*1024*1024*1024 {
		return fmt.Sprintf("%.2f GB", speed/(1024*1024*1024))
	}
	return fmt.Sprintf("%.2f TB", speed/(1024*1024*1024*1024))
}

func formatDurationSeconds(sec int64) string {
	if sec < 0 {
		sec = 0
	}
	return (time.Duration(sec) * time.Second).String()
}

type progressBar struct {
	total       int64
	current     int64
	start       time.Time
	lastGen     time.Time
	pending     string
	pendingCurr int64
	hasPending  bool
	generated   bool
}

func newProgressBar(total int64) *progressBar {
	return &progressBar{total: total, start: time.Now()}
}

func (p *progressBar) speed() float64 {
	elapsed := time.Since(p.start).Seconds()
	if elapsed <= 0 {
		return 0
	}
	return float64(p.current) / elapsed
}

func (p *progressBar) snapshot(final bool) string {
	if p.total > 0 {
		speed := p.speed()
		var timeStr string
		if final {
			timeStr = formatDurationSeconds(int64(time.Since(p.start).Seconds()))
		} else {
			var eta int64
			if speed > 0 {
				eta = int64(float64(p.total-p.current) / speed)
			}
			timeStr = formatDurationSeconds(eta)
		}
		percent := float64(p.current) / float64(p.total) * 100
		prefix := formatBytesInt(p.current) + " / " + formatBytesInt(p.total) + " "
		suffix := fmt.Sprintf(" %.2f %% %s %s", percent, formatSpeed(speed)+"/s", timeStr)
		barWidth := 123 - len(prefix) - len(suffix) - 2
		if barWidth < 0 {
			barWidth = 0
		}
		var bar string
		if p.current >= p.total {
			bar = strings.Repeat("=", barWidth)
		} else {
			eq := 0
			if barWidth > 0 {
				eq = int(float64(p.current) / float64(p.total) * float64(barWidth-1))
			}
			if eq < 0 {
				eq = 0
			}
			if barWidth > 0 {
				bar = strings.Repeat("=", eq) + ">" + strings.Repeat("_", barWidth-eq-1)
			}
		}
		return "\r" + prefix + "[" + bar + "]" + suffix
	}
	// unknown / zero total
	if final {
		var content string
		if p.current == 0 {
			content = fmt.Sprintf("0 B %s", formatDurationSeconds(int64(time.Since(p.start).Seconds())))
		} else {
			content = fmt.Sprintf("%s %s %s", formatBytesInt(p.current), formatSpeed(p.speed())+"/s", formatDurationSeconds(int64(time.Since(p.start).Seconds())))
		}
		if len(content) < 123 {
			content += strings.Repeat(" ", 123-len(content))
		}
		return "\r" + content
	}
	content := fmt.Sprintf("%s %s", formatBytesInt(p.current), formatSpeed(p.speed())+"/s")
	if len(content) < 123 {
		content += strings.Repeat(" ", 123-len(content))
	}
	return "\r" + content
}

func (p *progressBar) Write(b []byte) (int, error) {
	n := len(b)
	p.current += int64(n)
	now := time.Now()
	if !p.generated || now.Sub(p.lastGen) >= 200*time.Millisecond {
		line := p.snapshot(false)
		if p.hasPending {
			fmt.Print(p.pending)
		}
		p.pending = line
		p.pendingCurr = p.current
		p.hasPending = true
		p.generated = true
		p.lastGen = now
	}
	return n, nil
}

func (p *progressBar) Finish() {
	finalLine := p.snapshot(true)
	if p.hasPending {
		// For known-total downloads, a pending line that already
		// shows the final byte count is replaced by the final
		// rendering.  For unknown totals, both renderings appear.
		if p.total <= 0 || p.pendingCurr != p.current {
			fmt.Print(p.pending)
		}
	}
	fmt.Print(finalLine)
}

var _ io.Writer = (*progressBar)(nil)
EOF
"}

