		if err != nil {
			log.Fatal("Can't Write the body into file", err)
		}
		bar.Finish()
		return
	}

	if fi, err := os.Stdout.Stat(); err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
		terminalOutput = true
	} else {
		printValue = "b"
	}

	effectivePrint := printValue
